% Function in separate .m file or at end of script
function result = factorial(n)
    if n <= 1
        result = 1;
    else
        result = n * factorial(n - 1);
    end
end

% Multiple outputs
function [mn, mx, avg] = stats(v)
    mn = min(v);
    mx = max(v);
    avg = mean(v);
end
[a, b, c] = stats([3 1 4 1 5 9]);

% Default arguments with nargin
function result = power_val(base, exp)
    if nargin < 2
        exp = 2;
    end
    result = base ^ exp;
end
power_val(3)      % 9 (uses default)
power_val(3, 3)   % 27

% Varargs with varargin
function result = mysum(varargin)
    result = 0;
    for i = 1:nargin
        result += varargin{i};
    end
end

% Anonymous functions
square = @(x) x.^2;
add    = @(x, y) x + y;
square(5)     % 25

% Apply to arrays
arr = 1:5;
results = arrayfun(@(x) x^2+1, arr)  % [2 5 10 17 26]
